// Runnable demo: enforced, versioned, compatible schemas vs raw JSON.
package com.bank.schema.demo;

import java.util.*;
import java.util.logging.*;

public class SchemaRegistryDemo {
    private static final Logger log = Logger.getLogger(SchemaRegistryDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SchemaRegistry registry = new SchemaRegistry(); // backward compatibility mode
        String subject = "transfers-value";

        // v1: the agreed transfer schema
        Schema v1 = new Schema(1, new LinkedHashSet<>(Arrays.asList(
                "transferId", "fromAccount", "toAccount", "amount")));
        int idV1 = registry.register(subject, v1);

        // v2: add "currency" WITH a default -> backward compatible -> ACCEPTED
        Schema v2 = new Schema(2, new LinkedHashSet<>(Arrays.asList(
                "transferId", "fromAccount", "toAccount", "amount", "currency")));
        int idV2 = registry.register(subject, v2);

        // incompatible: remove required "amount" -> REJECTED at register time
        Schema bad = new Schema(3, new LinkedHashSet<>(Arrays.asList(
                "transferId", "fromAccount", "toAccount"))); // dropped amount
        registry.register(subject, bad);

        // Producer serializes with v2 schema id; message = id + data (not field names)
        AvroLikeSerializer serializer = new AvroLikeSerializer(registry);
        Map<String, String> data = new LinkedHashMap<>();
        data.put("transferId", "TXF-1"); data.put("fromAccount", "SAV2001");
        data.put("toAccount", "CUR3001"); data.put("amount", "50000");
        data.put("currency", "INR");
        byte[] wire = serializer.serialize(subject, idV2, data);

        // Consumer deserializes by fetching schema by id — reliable, no guessing
        new TransferConsumer(registry).consume(wire);
    }
}

