class Schema {
    private final int version;
    private final Set<String> fields;
    Schema(int version, Set<String> fields) { this.version = version; this.fields = fields; }
    int getVersion() { return version; }
    Set<String> getFields() { return fields; }
    // Backward compatible if it still contains all fields of the previous schema
    boolean isBackwardCompatibleWith(Schema previous) {
        return this.fields.containsAll(previous.getFields());
    }
    @Override public String toString() { return "v" + version + fields; }
}

// ─── Would be in SchemaRegistry.java ───
class SchemaRegistry {
    private static final Logger log = Logger.getLogger(SchemaRegistry.class.getName());
    private final Map<Integer, Schema> byId = new HashMap<>();
    private final Map<String, List<Schema>> bySubject = new HashMap<>();
    private int nextId = 1;
    // Register with BACKWARD compatibility enforcement
    int register(String subject, Schema schema) {
        List<Schema> history = bySubject.computeIfAbsent(subject, k -> new ArrayList<>());
        if (!history.isEmpty()) {
            Schema latest = history.get(history.size() - 1);
            if (!schema.isBackwardCompatibleWith(latest)) {
                log.severe(() -> "REJECT " + subject + " " + schema
                        + " — not backward compatible with " + latest
                        + " (would break existing consumers)");
                return -1;
            }
        }
        int id = nextId++;
        byId.put(id, schema);
        history.add(schema);
        log.info(() -> "REGISTERED " + subject + " " + schema + " as id=" + id);
        return id;
    }
    Schema getById(int id) { return byId.get(id); }
}

