class AvroLikeSerializer {
    private static final Logger log = Logger.getLogger(AvroLikeSerializer.class.getName());
    private final SchemaRegistry registry;
    AvroLikeSerializer(SchemaRegistry registry) { this.registry = registry; }
    // Wire format: [schemaId][compact values] — NO repeated field names like JSON
    byte[] serialize(String subject, int schemaId, Map<String, String> data) {
        Schema schema = registry.getById(schemaId);
        StringBuilder sb = new StringBuilder(schemaId + "|");
        for (String f : schema.getFields()) sb.append(data.getOrDefault(f, "")).append(",");
        log.info(() -> "SERIALIZE with schema id=" + schemaId
                + " -> wire=" + sb + " (field names NOT repeated on the wire)");
        return sb.toString().getBytes();
    }
}

// ─── Would be in TransferConsumer.java ───
class TransferConsumer {
    private static final Logger log = Logger.getLogger(TransferConsumer.class.getName());
    private final SchemaRegistry registry;
    TransferConsumer(SchemaRegistry registry) { this.registry = registry; }
    void consume(byte[] wire) {
        String msg = new String(wire);
        int schemaId = Integer.parseInt(msg.substring(0, msg.indexOf('|')));
        Schema schema = registry.getById(schemaId); // fetch exact schema by id
        String[] values = msg.substring(msg.indexOf('|') + 1).split(",");
        Map<String, String> decoded = new LinkedHashMap<>();
        int i = 0;
        for (String field : schema.getFields()) {
            decoded.put(field, i < values.length ? values[i] : "");
            i++;
        }
        log.info(() -> "DESERIALIZE using schema id=" + schemaId
                + " -> " + decoded + " (reliable, contract enforced)");
    }
}

